"""Mutalia-e-Quran XII PDF101: p.98 — verses 24:45–52 (24:53 begins at the foot; recorded with p.99). Run: python class12_quran_page101.py"""
from class12_quran_common import BOOK, Builder, rec, V


def p101():
    b = Builder()
    V(b, 24, 45, 'اور اللہ نے زمین پر چلنے والے ہر جاندار کو پانی سے پیدا فرمایا اُن میں سے کوئی اپنے پیٹ کے بل چلتا پھرتا ہے اور اُن میں سے کوئی دو ٹانگوں پر چلتا پھرتا ہے اور اُن میں سے کوئی چار پاؤں پر چلتا پھرتا ہے اللہ جو چاہتا ہے پیدا فرماتا ہے۔ بے شک اللہ ہر چیز پر پوری طرح قادر ہے۔',
      'او الله په ځمکه هر ګرځېدونکی ژوندی له اوبو پیدا کړی؛ له هغوی ځینې پر خپله خېټه ګرځي، ځینې پر دوو پښو ګرځي، او ځینې پر څلورو پښو ګرځي؛ الله چې څه وغواړي پیدا کوي یې؛ بې‌شکه الله پر هر شي پوره قادر دی.')
    V(b, 24, 46, 'یقیناً ہم نے واضح آیتیں نازل کیں اور اللہ جسے چاہتا ہے سیدھے راستے کی طرف ہدایت عطا فرماتا ہے۔',
      'یقیناً موږ روښانه آیتونه نازل کړل، او الله چې چا ته وغواړي سمې لارې ته یې لارښوونه کوي.')
    V(b, 24, 47, 'اور وہ کہتے ہیں ہم اللہ پر اور رسول (صلی اللہ علیہ وعلیٰ آلہٖ واصحابہٖ وسلم) پر ایمان لائے اور ہم نے اطاعت کی پھر اس کے بعد اُن میں سے ایک گروہ (اس دعوے کے بعد) منہ موڑ لیتا ہے اور ایسے لوگ (حقیقت میں) مومن نہیں ہیں۔',
      'او هغوی وايي: موږ پر الله او پر رسول (صلی الله علیه وعلی آله واصحابه وسلم) ایمان راوړ او اطاعت مو وکړ؛ بیا له دې وروسته له هغوی یوه ډله (له دې دعوې وروسته) مخ اړوي؛ او دا ډول خلک (په حقیقت کې) مؤمنان نه دي.')
    V(b, 24, 48, 'اور جب انھیں اللہ اور اُس کے رسول (صلی اللہ علیہ وعلیٰ آلہٖ واصحابہٖ وسلم) کی طرف بلایا جاتا ہے تاکہ وہ اُن کے درمیان (جھگڑوں کا) فیصلہ فرما دیں تب ان میں سے ایک گروہ روگردانی کرنے والا ہوتا ہے۔',
      'او کله چې هغوی الله او د هغه رسول (صلی الله علیه وعلی آله واصحابه وسلم) ته راوبلل شي تر څو د هغوی ترمنځ (د شخړو) پرېکړه وکړي، نو له هغوی یوه ډله مخ اړوونکې وي.')
    V(b, 24, 49, 'اور اگر فیصلہ اُن کے حق میں ہو تو وہ (رسول صلی اللہ علیہ وعلیٰ آلہٖ واصحابہٖ وسلم) کے بڑے فرماں بردار بن کر چلے آتے ہیں۔',
      'او که پرېکړه د هغوی په ګټه وي، نو د (رسول صلی الله علیه وعلی آله واصحابه وسلم) لوی فرمانبردار جوړ شي او راشي.')
    V(b, 24, 50, 'کیا اُن کے دلوں میں کوئی (نفاق کی) بیماری ہے یا وہ شک میں پڑے ہوئے ہیں یا انھیں اندیشہ ہے کہ اللہ اور اُس کا رسول (صلی اللہ علیہ وعلیٰ آلہٖ واصحابہٖ وسلم) ان پر ظلم کریں گے (نہیں) بلکہ وہی لوگ ظالم ہیں۔',
      'ایا د هغوی په زړونو کې د (نفاق) کومه ناروغي ده، یا په شک کې لوېدلي، یا وېرېږي چې الله او د هغه رسول (صلی الله علیه وعلی آله واصحابه وسلم) به پرې ظلم وکړي؟ (نه)، بلکې همدوی ظالمان دي.')
    V(b, 24, 51, 'بے شک مومنوں کی بات تو یہی ہوتی ہے کہ جب انھیں اللہ اور اُس کے رسول (صلی اللہ علیہ وعلیٰ آلہٖ واصحابہٖ وسلم) کی طرف بلایا جائے تاکہ وہ اُن کے درمیان فیصلہ فرمائیں کہ وہ کہیں ہم نے (احکام کو) سنا اور ہم نے (ان کی) اطاعت کی اور یہی لوگ فلاح پانے والے ہیں۔',
      'بې‌شکه د مؤمنانو خبره همدا وي چې کله الله او د هغه رسول (صلی الله علیه وعلی آله واصحابه وسلم) ته راوبلل شي تر څو د هغوی ترمنځ پرېکړه وکړي، نو وايي: موږ (حکمونه) واورېدل او (د هغو) اطاعت مو وکړ؛ او همدا خلک بریالي دي.')
    V(b, 24, 52, 'اور جو اللہ اور اُس کے رسول (صلی اللہ علیہ وعلیٰ آلہٖ واصحابہٖ وسلم) کی اطاعت کرے اور اللہ سے ڈرے اور اُس (کی نافرمانی) سے بچے تو یہی لوگ کامیاب ہونے والے ہیں۔',
      'او څوک چې د الله او د هغه رسول (صلی الله علیه وعلی آله واصحابه وسلم) اطاعت وکړي، له الله ووېرېږي او د هغه له (نافرمانۍ) ځان وساتي، نو همدا خلک کامیاب دي.')
